            // 初始刷新数据
            errorCatched(refreshAllData)();

            // 监听变量更新事件
            // 注意：这里需要根据您的实际环境调整事件名称
            eventOn(iframe_events.VARIABLES_UPDATED, (type, old_variables, new_variables) => {
                errorCatched(refreshAllData)();
            });

            // 设置定时刷新作为备选方案
            setInterval(() => {
                errorCatched(refreshAllData)();
            }, 3000);
        }

        // 文档加载完成后初始化
        $(document).ready(function() {
            // 等待变量系统就绪
            setTimeout(() => {
                errorCatched(init)();
            }, 1000);
        });
    </script>
</body>
